import{_ as r,a0 as i,w as l,s as p,ao as u,I as a,x as e,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"“戰鬥磚塊劇場”佔據了 Steam 上 Linux遊戲排行榜首位 | LCTT x X-CMD","titleTemplate":false,"description":"“戰鬥磚塊劇場”佔據了 Steam 上 Linux遊戲排行榜首位 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"“戰鬥磚塊劇場”佔據了 Steam 上 Linux遊戲排行榜首位 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"“戰鬥磚塊劇場”佔據了 Steam 上 Linux遊戲排行榜首位 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/BattleBlock Theater Now Rules the Steam for Linux Best-Selling List","title":"“戰鬥磚塊劇場”佔據了 Steam 上 Linux遊戲排行榜首位","tag":"201405","desc":""},"relativePath":"201405/BattleBlock Theater Now Rules the Steam for Linux Best-Selling List.md","filePath":"[post].md"}'),m={name:"201405/BattleBlock Theater Now Rules the Steam for Linux Best-Selling List.md"};function g(L,t,x,f,S,T){const s=i("Link");return l(),p("div",null,[t[11]||(t[11]=u('<h1 id="戰鬥磚塊劇場-佔據了-steam-上-linux遊戲排行榜首位" tabindex="-1">“戰鬥磚塊劇場”佔據了 Steam 上 Linux遊戲排行榜首位 <a class="header-anchor" href="#戰鬥磚塊劇場-佔據了-steam-上-linux遊戲排行榜首位" aria-label="Permalink to ““戰鬥磚塊劇場”佔據了 Steam 上 Linux遊戲排行榜首位”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/BattleBlock-Theater-Now-Rules-the-Steam-for-Linux-Best-Selling-List-442722-2.jpg" alt=""></p><p><strong>Steam for Linux平台在過去幾周接受了一些新遊戲，其中幾個在最暢銷名單裏有很高的提升。</strong></p><p><strong>小小世界2</strong> 取代原第十位併成為進入這個專屬名單裏的新遊戲。這款遊戲基於同名的幻想桌遊，這可能是此類型遊戲裏唯一一個有Linux版本的遊戲。</p><p><strong>足球經理2014</strong> 掉到了第九位，但鑑於這是Steam for Linux上最貴的遊戲，我們可以有把握地説他依然做的很好。不需要介紹，這款遊戲被認為是同類中做得最好的。</p><p><strong>反恐精英：起源</strong> ，遊戲結合了原作反恐精英的玩法，使用的是Source引擎，又回到了Steam for Linux最暢銷名單頂部，位於第八位。</p><p><strong>伊卡羅斯之炮在線版</strong> ，Muse Games開發的多玩家第一人稱射擊遊戲，遊戲有多個平台版本，包括Linux，現在它位於第七位而且它甚至打二五折。</p><p><strong>求生之路2</strong> ， Valve開發的多人合作第一人稱射擊遊戲，仍然是Linux平台最好的遊戲之一，位於第六位。</p><p><strong>星界邊境 Starbound</strong> ，呵呵魚工作室開發的一款程序生成冒險類遊戲，遊戲中玩家玩家扮演了一個逃離了自己星球而只能緊急降落在其他星球的角色，遊戲在第五位。這個遊戲仍然在開發中，在遊戲完成之前就有人買的事實説明了遊戲的質量。</p><p><strong>坎巴拉太空計劃</strong> ，一個多類型玩法的遊戲，遊戲中玩家必須要創建自己的太空項目而且要在不殺死宇航員的情況下發射成功，遊戲現在在第四位。</p><p><strong>蓋瑞模組 Garry&#39;s Mod</strong>, 一個物理沙箱，就其本身而言它甚至不算是個遊戲，它存在於第三空間，如果我們想想它的話它確實很奇怪。遊戲沒有單獨的玩家戰爭，但玩家有完全的自由。</p><p><strong>腐蝕Rust</strong>, 一款第一人稱生存遊戲，遊戲背景發生在一個持久的宇宙中，遊戲不再是第一位，但第二位也不是那麼糟糕。遊戲仍在開發中，沒有跡象表明多會兒會發布最終版本。</p><p>Steam for Linux的最暢名單中位於第一位是新領主，叫做 <strong>戰鬥磚塊劇場</strong> 。這是一款由The Behemoth創作併發布的2D戰鬥平台遊戲，遊戲特點是有趣的關卡設計和漂亮的圖案。</p><p>玩的開心！</p><hr>',15)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),n(s,{href:"http://news.softpedia.com/news/BattleBlock-Theater-Now-Rules-the-Steam-for-Linux-Best-Selling-List-442722.shtml"},{default:o(()=>[...t[0]||(t[0]=[e("http://news.softpedia.com/news/BattleBlock-Theater-Now-Rules-the-Steam-for-Linux-Best-Selling-List-442722.shtml",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("譯者：",-1)),n(s,{href:"https://github.com/linuhap"},{default:o(()=>[...t[2]||(t[2]=[e("linuhap",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),n(s,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const w=r(m,[["render",g]]);export{h as __pageData,w as default};
